            else:
                c_d += 1
        else:
            if o == 'C':
                d_c += 1
            else:
                d_d += 1

    pC_C = (c_c + 1) / (c_c + c_d + 2)
    pC_D = (d_c + 1) / (d_c + d_d + 2)
    cond = pC_C - pC_D

    streak_opp_D = 0
    if opp_last == 'D':
        for _, o in reversed(history):
            if o == 'D':
                streak_opp_D += 1
            else:
                break

