def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    opp_d_total = 0
    my_d_total = 0
    for i in range(n):
        a = history[i][0]
        b = history[i][1]
        if a == 'D':
            my_d_total += 1
        if b == 'D':
            opp_d_total += 1

    # If the opponent is an obvious pure defector early, stop feeding it.
    if n >= 4 and opp_d_total >= n:
        return 'D'

    # Build a cooperative baseline.
    if n < 5:
        return 'C'

    # If this opponent has never punished with any defection, switch to
    # controlled exploitation after a trust-building period.
    if opp_d_total == 0 and n >= 20:
        return 'D'

    # Estimate a small pairwise transition model for the opponent:
    # state = (my previous action, opponent previous action)
    # prob[s] = estimated probability opponent cooperates in the next round.
    total = [0.0, 0.0, 0.0, 0.0]
    coop = [0.0, 0.0, 0.0, 0.0]

    for i in range(1, n):
        pa = history[i - 1][0]
        pb = history[i - 1][1]
        if pa == 'C':
            idx = 0 if pb == 'C' else 1
        else:
            idx = 2 if pb == 'C' else 3

        age = n - 1 - i
        if age <= 8:
            w = 1.0
        elif age <= 20:
            w = 0.45
        else:
            w = 0.12

        total[idx] += w
        if history[i][1] == 'C':
            coop[idx] += w

    # Cautious priors: assume that an unjustified cooperation after our D
    # is unlikely until observed; do not over-explore.
    prior = [0.87, 0.58, 0.22, 0.10]
    pw = 4.0
    prob = [0.0, 0.0, 0.0, 0.0]
    for s in range(4):
        p = (prior[s] * pw + coop[s]) / (pw + total[s])
        if p < 0.02:
            p = 0.02
        if p > 0.98:
            p = 0.98
        prob[s] = p

    my_last = history[-1][0]
    opp_last = history[-1][1]
    if my_last == 'C':
        cur = 0 if opp_last == 'C' else 1
    else:
        cur = 2 if opp_last == 'C' else 3

    # Recent outcome statistics for direct exploitation / hostility rules.
    start12 = n - 12 if n >= 12 else 0
    start20 = n - 20 if n >= 20 else 0

    recent_cd = 0
    recent_dc = 0
    recent_op_d = 0
    recent20_op_d = 0

    for i in range(start12, n):
        a = history[i][0]
        b = history[i][1]
        if a == 'C' and b == 'D':
            recent_cd += 1
        if a == 'D' and b == 'C':
            recent_dc += 1
        if b == 'D':
            recent_op_d += 1

    for i in range(start20, n):
        if history[i][1] == 'D':
            recent20_op_d += 1

    dc_streak = 0
    i = n - 1
    while i >= 0:
        if history[i][0] == 'D' and history[i][1] == 'C':
            dc_streak += 1
            i -= 1
        else:
            break

    cd_streak = 0
    i = n - 1
    while i >= 0:
        if history[i][0] == 'C' and history[i][1] == 'D':
            cd_streak += 1
            i -= 1
        else:
            break

    # Exploit opponents that tolerate our exploitation repeatedly.
    if dc_streak >= 3:
        return 'D'
    if dc_streak >= 2 and recent_op_d <= 1:
        return 'D'
    if recent_dc >= 2 and recent_cd == 0:
        return 'D'
    if cur == 2 and recent_cd <= 1 and opp_d_total <= 2 and n >= 15:
        return 'D'

    # Against clearly uncooperative behavior, avoid unilateral C.
    if recent_op_d >= 6:
        return 'D'
    if opp_d_total * 10 >= n * 6 and opp_d_total > 2:
        return 'D'
    if n >= 20 and opp_d_total * 4 >= n and (cur == 1 or recent_dc >= 4):
        return 'D'

    # Finite-horizon expected-value calculation under the learned transition
    # probabilities.  This automatically defers exploitation when it is likely
    # to cause a costly retaliation.
    R = 100 - n
    if R <= 1:
        return 'D'

    V = [0.0, 0.0, 0.0, 0.0]
    for _ in range(R - 1):
        nv = [0.0, 0.0, 0.0, 0.0]
        for s in range(4):
            p = prob[s]
            q = 1.0 - p
            vC = p * 3.0 + p * V[0] + q * V[1]
            vD = p * 5.0 + q * 1.0 + p * V[2] + q * V[3]
            nv[s] = vD if vD > vC else vC
        V = nv

    p = prob[cur]
    q = 1.0 - p
    vC = p * 3.0 + p * V[0] + q * V[1]
    vD = p * 5.0 + q * 1.0 + p * V[2] + q * V[3]

    # Bias toward cooperation in clean cooperative states and in short
    # conflicts with otherwise cooperative opponents.
    bias = 0.0
    if cur == 0 and recent_cd == 0 and recent_dc == 0:
        bias = 0.5
    elif cur == 1:
        if cd_streak <= 1 and recent_cd <= 2 and opp_d_total * 2 <= n:
            bias = 0.6
        elif recent_cd <= 3 and opp_d_total * 3 <= n:
            bias = 0.25
    elif cur == 3:
        if recent_cd <= 2 and recent_op_d <= 3 and opp_d_total * 2 <= n:
            bias = 0.7
        elif recent_op_d <= 2 and opp_d_total * 3 <= n:
            bias = 0.35

    if vD > vC + bias:
        return 'D'
    return 'C'

