def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_m, last_o = history[-1]

    opp_d = 0
    my_d = 0
    cc_count = 0
    for m, o in history:
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1
        if m == 'C' and o == 'C':
            cc_count += 1

    s = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            s += 1
        else:
            break

    cd = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'D':
            cd += 1
        else:
            break

    start = n - 10
    if start < 0:
        start = 0

    rec_d = 0
    rec_cc = 0
    for i in range(start, n):
        m, o = history[i]
        if o == 'D':
            rec_d += 1
        if m == 'C' and o == 'C':
            rec_cc += 1

    rounds_left = 100 - n
    if rounds_left <= 1:
        return 'D'

    if n >= 3 and opp_d == n and rec_d >= 3:
        return 'D'

    if rounds_left <= 3:
        ret = 0
        ops = 0
        st = n - 20
        if st < 1:
            st = 1
        for i in range(st, n):
            if history[i - 1][0] == 'D':
                ops += 1
                if history[i][1] == 'D':
                    ret += 1
        if last_o == 'C':
            if my_d >= 1 and ops >= 2 and ret * 3 <= ops:
                return 'D'
        elif last_o == 'D':
            if opp_d <= 2 and cd == 0:
                return 'D'

    if last_o == 'C':
        if n >= 3 and my_d >= 1:
            end_streak = 0
            for i in range(n - 2, -1, -1):
                if history[i][1] == 'D':
                    end_streak += 1
                else:
                    break
            if end_streak == 2 and opp_d * 10 <= n * 4 and rec_cc >= 2:
                return 'D'
        return 'C'

    if cd >= 2:
        return 'D'

    if rec_d >= 9 and s >= 7:
        return 'D'

    if s <= 1:
        if rec_d >= 8:
            return 'D'
        return 'C'

    if s == 2:
        return 'D'

    if s == 3:
        if opp_d * 10 <= n * 3 + 10:
            return 'C'
        return 'D'

    if s == 4:
        if opp_d * 10 <= n * 3 + 15:
            return 'C'
        return 'D'

    if opp_d * 100 <= n * 25 and rec_cc >= 3:
        return 'C'

    return 'D'

