def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    total_punish = 0
    total_forgive = 0
    total_unprovoked = 0

    for i in range(n):
        me, op = history[i]
        if op == 'C':
            opp_c += 1
        if i > 0:
            pm = history[i - 1][0]
            if pm == 'D':
                if op == 'D':
                    total_punish += 1
                else:
                    total_forgive += 1
            if pm == 'C' and op == 'D':
                total_unprovoked += 1

    opp_rate = opp_c / n

    W = 12 if n >= 12 else n
    rec_c = 0
    if W > 0:
        rec_start = n - W
        for i in range(rec_start, n):
            if history[i][1] == 'C':
                rec_c += 1
    rec_d = W - rec_c

    start = max(1, n - W)
    recent_punish = 0
    recent_forgive = 0
    recent_unprovoked = 0
    for i in range(start, n):
        pm = history[i - 1][0]
        op = history[i][1]
        if pm == 'D':
            if op == 'D':
                recent_punish += 1
            else:
                recent_forgive += 1
        elif pm == 'C' and op == 'D':
            recent_unprovoked += 1

    streak_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            streak_c += 1
        else:
            break

    streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_d += 1
        else:
            break

    cc_streak = 0
    for i in range(n - 1, -1, -1):
        me, op = history[i]
        if me == 'C' and op == 'C':
            cc_streak += 1
        else:
            break

    last_m, last_o = history[-1]

    if opp_c == 0 and n >= 5:
        return 'D'
    if streak_d >= 5:
        return 'D'
    if rec_c == 0 and n >= 12:
        return 'D'
    if opp_rate < 0.18 and n >= 20:
        return 'D'

    if last_m == 'C' and streak_d == 4:
        return 'D'

    exploit_evidence = (
        total_forgive >= 1 and
        total_forgive + total_unprovoked >= total_punish + 1
    )

    if exploit_evidence:
        if last_o == 'C':
            return 'D'
        if last_m == 'D' and streak_d <= 3 and rec_c >= 2:
            if recent_unprovoked >= 1 or total_unprovoked >= 2:
                return 'D'
        return 'C'

    if last_o == 'D':
        if n <= 14 or rec_c >= max(2, W // 2) or (opp_rate > 0.40 and streak_d <= 4):
            return 'C'
        return 'D'

    if last_m == 'D':
        return 'C'

    if opp_rate >= 0.50 and rec_c >= max(2, W // 2) and total_punish == 0 and total_forgive == 0:
        if opp_rate < 0.98 and cc_streak >= 2 and n >= 10:
            if n < 97 and (rng.random() < 0.18 or n % 17 == 0):
                return 'D'
        if opp_rate >= 0.98 and cc_streak >= 18 and n >= 20:
            if n < 97 and (rng.random() < 0.08 or n % 23 == 0 or n >= 35):
                return 'D'
        if n == 98 and rec_c >= max(1, W - 2) and opp_rate >= 0.80:
            return 'D'

    return 'C'

