    s20 = n - 20
    if s20 < 0:
        s20 = 0
    c20 = 0
    l20 = n - s20
    for x in op[s20:]:
        if x == 'C':
            c20 += 1
    r20_rate = c20 / l20

    last_op = op[-1]
    run = 0
    for x in reversed(op):
        if x == last_op:
            run += 1
        else:
            break

