        co = op[i]
        if pm == 'C':
            if co == 'C':
                CC += w
            else:
                CD += w
        else:
            if co == 'C':
                DC += w
            else:
                DD += w

    total_D = DC + DD
    total_C = CC + CD
    pD = (DC + 1.0) / (total_D + 2.0)
    pC = (CC + 1.0) / (total_C + 2.0)

