def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            opp_d_streak += 1
        else:
            break

    own_c_streak = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'C':
            own_c_streak += 1
        else:
            break

    w6 = min(6, n)
    rec6_c = sum(1 for x in opp[n - w6:] if x == 'C')

    w10 = min(10, n)
    rec10_c = sum(1 for x in opp[n - w10:] if x == 'C')

    failed_starts = 0
    for i in range(1, n):
        if me[i] == 'C' and opp[i] == 'D' and me[i - 1] == 'D':
            failed_starts += 1

    d_c = 0
    d_d = 0
    mimic = 0
    for i in range(1, n):
        p = me[i - 1]
        q = opp[i]
        if p == 'D':
            if q == 'C':
                d_c += 1
            else:
                d_d += 1
        if q == p:
            mimic += 1

    d_tot = d_c + d_d

    prev_cd = False
    if n >= 2 and me[-2] == 'C' and opp[-2] == 'D':
        prev_cd = True

    if last_opp == 'D':
        if last_me == 'C' and own_c_streak == 1 and opp_d_streak >= 3:
            return 'C'

        if last_me == 'C' and opp_d_streak == 1:
            if not prev_cd and (failed_starts == 0 or rec6_c >= 4):
                return 'C'

        if last_me == 'D' and opp_d_streak >= 3:
            if failed_starts == 0 or rec6_c >= 5:
                return 'C'

        return 'D'

    if opp_d == 0:
        if n >= 6 and d_c >= 1:
            return 'D'
        if n >= 5 and rng.random() < 0.04:
            return 'D'

    if n >= 10 and rec10_c >= 9 and rng.random() < 0.03:
        return 'D'

    if n >= 8 and rec10_c == 10 and d_c >= 1 and d_d == 0:
        return 'D'

    if n >= 8 and opp_c * 2 >= n:
        if d_tot >= 4 and d_c >= d_d + 2 and d_c * 2 >= d_tot:
            return 'D'

    if (
        n >= 10
        and opp_c * 5 >= n * 3
