        return 'C'

    opp_d = 0
    opp_c = 0
    my_d = 0
    my_c = 0
    for m, o in history:
        if o == 'D':
            opp_d += 1
        else:
            opp_c += 1
        if m == 'D':
            my_d += 1
        else:
            my_c += 1

    last_me, last_op = history[-1]

    if n == 99:
        return 'D'
    if opp_c == 0:
        return 'D'

    opp_d_streak = 0
    while opp_d_streak < n and history[n - 1 - opp_d_streak][1] == 'D':
        opp_d_streak += 1

    prev_c_streak = 0
    j = n - 1 - opp_d_streak
    while j >= 0 and history[j][1] == 'C':
        prev_c_streak += 1
        j -= 1

    dd_streak = 0
    for i in range(n - 1, -1, -1):
        m, o = history[i]
        if m == 'D' and o == 'D':
            dd_streak += 1
        else:
            break

    dc_streak = 0
    for i in range(n - 1, -1, -1):
        m, o = history[i]
        if m == 'D' and o == 'C':
            dc_streak += 1
        else:
            break

    recent_my_d = 0
    start = n - 4
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][0] == 'D':
            recent_my_d += 1

    recent_opp_c = 0
