def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    opp_d = 0
    my_c = 0
    my_d = 0

    for mine, opp in history:
        if mine == 'C':
            my_c += 1
        else:
            my_d += 1
        if opp == 'C':
            opp_c += 1
        else:
            opp_d += 1

    aC_c = 0
    aC_d = 0
    aD_c = 0
    aD_d = 0

    for i in range(1, n):
        prev = history[i - 1][0]
        curr = history[i][1]
        if prev == 'C':
            if curr == 'C':
                aC_c += 1
            else:
                aC_d += 1
        else:
            if curr == 'C':
                aD_c += 1
            else:
                aD_d += 1

    samples_C = aC_c + aC_d
    samples_D = aD_c + aD_d

    opp_rate = opp_c / float(n)

    recent_len = min(10, n)
    recent_d = 0
    for i in range(n - recent_len, n):
        if history[i][1] == 'D':
            recent_d += 1
    recent_rate = 1.0 - (recent_d / float(recent_len)) if recent_len else 1.0

    last_my, last_opp = history[-1]

    run_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            run_d += 1
        else:
            break

    provoked = False
    if last_opp == 'D' and n >= 2:
        provoked = history[-2][0] == 'D'

    if opp_c == 0:
        return 'D'

    if n >= 12 and opp_d == 0 and my_d == 0:
        return 'D'

    if samples_D >= 1 and aD_d == 0 and opp_rate >= 0.55:
        return 'D'

    if samples_D >= 2:
        p_d_d = aD_d / float(samples_D)
        if samples_C > 0:
            p_d_c = aC_d / float(samples_C)
        else:
            p_d_c = opp_d / float(n)

        if p_d_d <= 0.60 and (p_d_d - p_d_c) <= 0.15 and opp_rate >= 0.30:
            return 'D'

    if opp_rate < 0.35:
        return 'D'

    if last_opp == 'D':
        if provoked and run_d <= 5 and opp_rate >= 0.50:
            return 'C'

        if run_d >= 2:
            return 'D'

        if opp_rate >= 0.65 and recent_rate >= 0.55:
            return 'C'

        if samples_C >= 3 and aC_c > aC_d:
            return 'C'

        return 'D' if opp_rate < 0.65 else 'C'

    if last_my == 'D' and samples_D == 0:
        return 'C'

    return 'C'

