def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    remaining = 100 - n
    if remaining <= 2:
        return 'D'

    my_last, opp_last = history[-1]

    opp_d = 0
    for _, o in history:
        if o == 'D':
            opp_d += 1

    tolerant_events = 0
    total_failed = 0
    for i in range(1, n):
        pm, po = history[i - 1]
        cm, co = history[i]
        if cm == 'C' and co == 'D' and pm == 'D' and po == 'D':
            total_failed += 1
        if pm == 'D' and po == 'C' and cm == 'C' and co == 'C':
            tolerant_events += 1

    if (
        opp_d == 0 and
        total_failed == 0 and
        my_last == 'C' and
        opp_last == 'C' and
        n >= 35 and
        remaining > 20 and
        rng.random() < 0.015
    ):
        return 'D'

    start_recent = n - 10
    if start_recent < 0:
        start_recent = 0

    recent_opp_c = 0
    for i in range(start_recent, n):
        if history[i][1] == 'C':
            recent_opp_c += 1

    start_fail = n - 10
    if start_fail < 1:
        start_fail = 1

    recent_failed = 0
    for i in range(start_fail, n):
        pm = history[i - 1][0]
        po = history[i - 1][1]
        cm = history[i][0]
        co = history[i][1]
        if cm == 'C' and co == 'D' and pm == 'D' and po == 'D':
            recent_failed += 1

    if my_last == 'C' and opp_last == 'D':
        if history[-2][0] == 'D' and history[-2][1] == 'D':
            return 'D'

    mutual_d_streak = 0
    for m, o in reversed(history):
        if m == 'D' and o == 'D':
            mutual_d_streak += 1
        else:
            break

    if (
        mutual_d_streak >= 3 and
        recent_failed == 0 and
        (total_failed == 0 or recent_opp_c >= 4)
    ):
        return 'C'

    opp_d_rate = opp_d / n

    if opp_d >= 3 and opp_d >= n // 2:
        return 'D'

    if opp_last == 'D' and history[-2][1] == 'D':
        return 'D'

    if (
        tolerant_events >= 1 and
        total_failed == 0 and
        opp_d_rate < 0.2 and
        recent_opp_c >= 7 and
        remaining > 12
    ):
        if my_last == 'D' and opp_last == 'C':
            if rng.random() < 0.28:
                return 'D'
        elif my_last == 'C' and opp_last == 'C':
            if rng.random() < 0.09:
                return 'D'

    return 'C'

