def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_d = 0
    for x in op:
        if x == 'D':
            opp_d += 1

    opp_c = n - opp_d
    if opp_c == 0:
        return 'D'

    if opp_d == 0:
        if n >= 20:
            return 'D'
        return 'C'

    recent10_d = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if op[i] == 'D':
            recent10_d += 1

    samples = 0
    punished = 0
    if n >= 2:
        for i in range(n - 1):
            if my[i] == 'D':
                samples += 1
                if op[i + 1] == 'D':
                    punished += 1

    if samples >= 4 and punished * 2 <= samples and recent10_d <= 6 and opp_d * 2 <= n:
        return 'D'

    if opp_d * 10 >= n * 9 and recent10_d == 10:
        return 'D'

    run_dd = 0
    i = n - 1
    while i >= 0 and my[i] == 'D' and op[i] == 'D':
        run_dd += 1
        i -= 1

    m_last = my[-1]
    o_last = op[-1]

    if o_last == 'D':
        if m_last == 'D':
            if run_dd >= 6:
                return 'C'
            return 'D'
        else:
            if n >= 2:
                pm = my[-2]
                po = op[-2]
                if pm == 'D' and po == 'C':
                    return 'C'
                if pm == 'D' and po == 'D':
                    return 'C'
            return 'D'

    if o_last == 'C':
        if m_last == 'D':
            if n >= 2 and my[-2] == 'D' and op[-2] == 'C':
                if recent10_d <= 2 and opp_d * 3 <= n:
                    return 'D'
            return 'C'
        else:
            if n > 30 and opp_d * 5 < n and rng.random() < 0.01:
                return 'D'
            return 'C'

    return 'C'

