def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    if n == 1:
        return 'C' if last_opp == 'C' else 'D'

    opp_c = 0
    opp_d = 0
    dc = 0
    cd = 0

    for a, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

        if a == 'C':
            if b == 'D':
                cd += 1
        else:
            if b == 'C':
                dc += 1

    if opp_c == 0:
        return 'D'

    opp_rate = opp_c / n

    recent10_c = sum(1 for a, b in history[-10:] if b == 'C')
    recent15_c = sum(1 for a, b in history[-15:] if b == 'C')

    streak_d = 0
    for a, b in reversed(history):
        if b == 'D':
            streak_d += 1
        else:
            break

