def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n < 5:
        return 'C'

    my_last, opp_last = history[-1]

    o_streak = 0
    i = n - 1
    while i >= 0:
        if history[i][1] == 'D':
            o_streak += 1
        else:
            break
        i -= 1

    recent6 = history[-6:]
    recent8 = history[-8:]
    r6_c = sum(1 for _, b in recent6 if b == 'C')
    r8_d = sum(1 for _, b in recent8 if b == 'D')
    total_d = sum(1 for _, b in history if b == 'D')
    total_c = n - total_d

    if o_streak >= 5 or (r8_d >= 5 and total_d > total_c):
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if r6_c >= 1:
                return 'C'
            return 'D'

        if history[-2][0] == 'D' and history[-2][1] == 'D' and r6_c >= 1:
            return 'C'

        return 'D'

    if my_last == 'D':
        return 'D'

    return 'C'

