    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, op_last = history[-1]

    opp_def = 0
    for _, o in history:
        if o == 'D':
            opp_def += 1

    rec_opp_def = 0
    for _, o in history[-10:]:
        if o == 'D':
            rec_opp_def += 1

    streak_op_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_op_d += 1
        else:
            break

    streak_op_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            streak_op_c += 1
        else:
            break

    cd_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C' and history[i][1] == 'D':
            cd_streak += 1
        else:
            break

    start = n - 12
    if start < 0:
        start = 0

    d_next = 0
    d_to_c = 0
    for i in range(start, n - 1):
        if history[i][0] == 'D':
            d_next += 1
            if history[i + 1][1] == 'C':
                d_to_c += 1

    resp_d_c = d_to_c / d_next if d_next else 0.0

    hostile = (
        opp_def >= max(4, int(n * 0.45)) or
        (n >= 8 and rec_opp_def >= 7) or
        (n >= 2 and opp_def == n) or
        (streak_op_d >= 5 and opp_def >= 5)
