    opp_d = 0
    for me, op in history:
        if me == 'D':
            my_d += 1
        if op == 'D':
            opp_d += 1
    opp_c = n - opp_d

    last_me, last_op = history[-1]

    # Trailing streaks.
    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    # Recent five opponent actions.
    recent5 = history[-5:] if n >= 5 else history
    recent5_opp_c = 0
    for pair in recent5:
        if pair[1] == 'C':
            recent5_opp_c += 1

    # Transition statistics: opponent current action vs our previous action.
    w = min(n, 15)
    start_i = max(1, n - w)

    after_c_total = 0
    after_c_d = 0
    after_d_total = 0
    after_d_d = 0
    copy_total = 0
    copy_match = 0

    for i in range(start_i, n):
        prev_me = history[i - 1][0]
        opp_now = history[i][1]

        copy_total += 1
        if opp_now == prev_me:
            copy_match += 1

        if prev_me == 'C':
            after_c_total += 1
            if opp_now == 'D':
                after_c_d += 1
        else:
            after_d_total += 1
            if opp_now == 'D':
                after_d_d += 1

