    for i in range(n - 1, -1, -1):
        if my[i] == 'D':
            my_d_streak += 1
        else:
            break

    copy_m = 0
    copy_t = 0
    start_copy = 1
    if n > 20:
        start_copy = n - 20
    for i in range(start_copy, n):
        copy_t += 1
        if my[i - 1] == opp[i]:
            copy_m += 1
    copy_rate = 1.0
    if copy_t > 0:
