def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my_last, opp_last = history[-1]
    if n == 1:
        if opp_last == 'C':
            return 'C'
        return 'D'

    prev_my, prev_opp = history[-2]

    opp_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1

    recent_c = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_c += 1

    d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        d_streak += 1
        i -= 1

    if opp_last == 'C':
        if my_last == 'D':
            return 'D'
        if n < 90 and recent_c >= 5 and rng.random() < 0.04:
            return 'D'
        return 'C'

