def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    opp_d_streak = 0
    for _, o in reversed(history):
        if o == 'D':
            opp_d_streak += 1
        else:
            break

    own_d_streak = 0
    for m, _ in reversed(history):
        if m == 'D':
            own_d_streak += 1
        else:
            break

    total_opp_d = 0
    total_own_d = 0
    for m, o in history:
        if m == 'D':
            total_own_d += 1
        if o == 'D':
            total_opp_d += 1

    start = n - 20
    if start < 0:
        start = 0

    recent_opp_d = 0
    indep_d = 0
    punish_d = 0
    forgive_d = 0

    for i in range(n):
        m, o = history[i]
        if i >= start and o == 'D':
            recent_opp_d += 1
        if i > 0:
            prev_m = history[i - 1][0]
            cur_o = history[i][1]
            if prev_m == 'C' and cur_o == 'D':
                indep_d += 1
            elif prev_m == 'D':
                if cur_o == 'D':
                    punish_d += 1
                else:
                    forgive_d += 1

    if n == 99:
        return 'D'

    if n == 98:
        if recent_opp_d >= 6 or indep_d >= 4:
            return 'D'
        if forgive_d >= 1 and punish_d == 0 and indep_d <= 1:
            return 'D'
        return 'C'

    extreme_hostile = (
        recent_opp_d >= 16 and indep_d >= 5
