def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_ops, opp_ops = zip(*history)
    opp_c = opp_ops.count('C')
    rate = (opp_c + 1.0) / (n + 2.0)
    my_last, opp_last = history[-1]

    opp_streak_D = 0
    i = n - 1
    while i >= 0 and opp_ops[i] == 'D':
        opp_streak_D += 1
        i -= 1

    opp_streak_C = 0
    i = n - 1
    while i >= 0 and opp_ops[i] == 'C':
        opp_streak_C += 1
        i -= 1

    np = 0
    pu = 0
    for i in range(n - 1):
        if my_ops[i] == 'D':
            if opp_ops[i + 1] == 'C':
                np += 1
            else:
                pu += 1

    looks_periodic = False
    if n >= 14 and opp_c > 0:
        d_streaks = []
        c_streaks = []
        prev = opp_ops[0]
        run = 1
        for o in opp_ops[1:]:
            if o == prev:
                run += 1
            else:
                if prev == 'D':
                    d_streaks.append(run)
                else:
                    c_streaks.append(run)
                prev = o
                run = 1

        d2 = 0
        other_d = 0
        for s in d_streaks:
            if s == 2:
                d2 += 1
            else:
                other_d += 1

        c3 = 0
        for s in c_streaks:
            if s >= 3:
                c3 += 1

        if d2 >= 2 and other_d == 0 and c3 >= 2 and rate > 0.55:
            looks_periodic = True

    exploit = False
    if np == 1 and pu == 0 and (rate > 0.55 or looks_periodic):
        exploit = True
    elif np >= 2 and np > pu and rate > 0.45:
        exploit = True
    elif np >= 4 and np > pu and rate > 0.40:
        exploit = True
    elif looks_periodic and (np + pu == 0 or np > pu):
        exploit = True

    if exploit:
        return 'D'

    if my_last == 'D' and opp_last == 'C':
        return 'C'

    if np == 0 and pu == 0:
        if rate <= 0.35 and opp_last == 'D':
            return 'D'

        if looks_periodic:
            return 'D'

        if opp_c == n:
            if n >= 12 and opp_last == 'C':
                return 'D'
            return 'C'

        if opp_last == 'D':
            if opp_streak_D >= 4 and rate > 0.55:
                return 'D'
            if opp_streak_D >= 2 and rate <= 0.45:
                return 'D'
            return 'C'

        return 'C'

    if rate <= 0.35:
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if rate > 0.60 and pu >= np and opp_streak_D <= 5:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
            if rate > 0.55:
                return 'C'

        if rate > 0.75 and opp_streak_D <= 2:
            return 'C'

        if rate > 0.65 and opp_streak_D <= 3:
            return 'C'

        if np > 0 and pu == 0:
            return 'C'

        return 'D'

    if rate <= 0.45:
        return 'D'

    if pu >= np and pu > 0:
        return 'C'

    if looks_periodic:
        return 'D'

    return 'C'

