def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    rem = 100 - n
    if rem <= 0:
        return 'D'
    if rem == 1:
        return 'D'

    my_seq = [h[0] for h in history]
    opp_seq = [h[1] for h in history]

    opp_coops = 0
    my_coops = 0
    for i in range(n):
        if opp_seq[i] == 'C':
            opp_coops += 1
        if my_seq[i] == 'C':
            my_coops += 1

    opp_rate = opp_coops / n
    my_rate = my_coops / n
    opp_defs = n - opp_coops

    rl = 12 if n > 12 else n
    recent_opp = opp_seq[-rl:]
    rec_c = 0
    for x in recent_opp:
        if x == 'C':
            rec_c += 1
    rec_d = rl - rec_c
    recent_rate = rec_c / rl

    rs = n - rl
    if rs < 1:
        rs = 1
    rh = 0
    rt = 0
    for i in range(rs, n):
        if my_seq[i - 1] == opp_seq[i]:
            rh += 1
        rt += 1
    react_rate = rh / rt if rt > 0 else 1.0

    my_last = my_seq[-1]
    opp_last = opp_seq[-1]

    opp_val = opp_last
    opp_streak = 0
    for x in reversed(opp_seq):
        if x == opp_val:
            opp_streak += 1
        else:
            break

