    my_val = my_last
    my_streak = 0
    for x in reversed(my_seq):
        if x == my_val:
            my_streak += 1
        else:
            break

    periodic = False
    if opp_coops > 0 and opp_defs > 0 and rec_c >= 3 and rec_d >= 3 and rl >= 8 and react_rate < 0.6:
        best_p = 0
        best_acc = 0.0
        maxp = rl - 3
        if maxp > 7:
            maxp = 7
        for p in range(2, maxp + 1):
            tot = rl - p
            if tot < 3:
                continue
            hits = 0
            for i in range(p, rl):
                if recent_opp[i] == recent_opp[i - p]:
                    hits += 1
            acc = hits / tot
            if acc > best_acc:
                best_acc = acc
                best_p = p
        if best_p != 0 and best_acc >= 0.85:
            periodic = True

    if periodic:
        return 'D'

    if opp_last == 'C':
