    d_after_c = 0
    c_after_d = 0
    d_after_d = 0
    for i in range(n - 1):
        m = history[i][0]
        o = history[i + 1][1]
        if m == 'C':
            if o == 'C':
                c_after_c += 1
            else:
                d_after_c += 1
        else:
            if o == 'C':
                c_after_d += 1
            else:
                d_after_d += 1

    total_c = c_after_c + d_after_c
    total_d = c_after_d + d_after_d

    if total_c > 0:
        p_c = c_after_c / float(total_c)
    else:
        p_c = opp_rate

    if total_d > 0:
        p_d = c_after_d / float(total_d)
    else:
        p_d = None

    same_opp = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            same_opp += 1
        else:
            break

    if opp_last == 'D':
        streak_opp_D = same_opp
        streak_opp_C = 0
