def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'
    if n == 99:
        return 'D'

    my = [0 if h[0] == 'C' else 1 for h in history]
    op = [0 if h[1] == 'C' else 1 for h in history]
    cap = 6
    sdim = cap + 1

    runs = []
    r = 0
    for b in op:
        if b == 1:
            r += 1
        else:
            r = 0
        runs.append(r)

    opp_D_streak = 0
    for b in reversed(op):
        if b == 1:
            opp_D_streak += 1
        else:
            break

    opp_C_streak = 0
    for b in reversed(op):
        if b == 0:
            opp_C_streak += 1
        else:
            break

    my_D_streak = 0
    for a in reversed(my):
        if a == 1:
            my_D_streak += 1
        else:
            break

    my_C_streak = 0
    for a in reversed(my):
        if a == 0:
            my_C_streak += 1
        else:
            break

    mutual_D_streak = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 1 and op[i] == 1:
            mutual_D_streak += 1
        else:
            break

    opp_c = 0
    for b in op:
        if b == 0:
            opp_c += 1
    overall_opp = opp_c / n

    rl = min(10, n)
    recent_opp = 0.0
    for i in range(n - rl, n):
        if op[i] == 0:
            recent_opp += 1.0
    recent_opp /= rl

    rl20 = min(20, n)
    recent20 = 0.0
    for i in range(n - rl20, n):
        if op[i] == 0:
            recent20 += 1.0
    recent20 /= rl20

    el = min(10, n)
    early_opp = 0.0
    for i in range(el):
        if op[i] == 0:
            early_opp += 1.0
    early_opp /= el

    mrl = min(10, n)
    my_c_recent = 0.0
    for i in range(n - mrl, n):
        if my[i] == 0:
            my_c_recent += 1.0
    my_c_recent /= mrl

    friendly = (
        overall_opp >= 0.45 and
        early_opp >= 0.40 and
        (recent_opp >= 0.20 or recent20 >= 0.35) and
        my_c_recent >= 0.40
    )

    num = [[0.0 for _ in range(sdim)] for _ in range(2)]
    den = [[0.0 for _ in range(sdim)] for _ in range(2)]
    my_num = [0.0, 0.0]
    my_den = [0.0, 0.0]
    run_num = [0.0 for _ in range(sdim)]
    run_den = [0.0 for _ in range(sdim)]
    base_num = 0.0
    base_den = 0.0

    global_prior = (opp_c + 1.0) / (n + 2.0)

    for j in range(1, n):
        age = n - 1 - j
        if age < 4:
            w = 1.0
        elif age < 9:
            w = 0.85
        elif age < 16:
            w = 0.65
        elif age < 31:
            w = 0.45
        elif age < 61:
            w = 0.25
        else:
            w = 0.10

        mv = my[j - 1]
        rv = runs[j - 1]
        if rv > cap:
            rv = cap
        val = 1.0 if op[j] == 0 else 0.0

        num[mv][rv] += w * val
        den[mv][rv] += w
        my_num[mv] += w * val
        my_den[mv] += w
        run_num[rv] += w * val
        run_den[rv] += w
        base_num += w * val
        base_den += w

    if base_den > 0.0:
        base_p = (base_num + global_prior + 1.0) / (base_den + 3.0)
    else:
        base_p = global_prior

    alpha = 3.0
    my_p = [base_p, base_p]
    if my_den[0] > 0.0:
        my_p[0] = (my_num[0] + alpha * base_p) / (my_den[0] + alpha)
    if my_den[1] > 0.0:
        my_p[1] = (my_num[1] + alpha * base_p) / (my_den[1] + alpha)

    run_p = [base_p for _ in range(sdim)]
    for rv in range(sdim):
        if run_den[rv] > 0.0:
            run_p[rv] = (run_num[rv] + alpha * base_p) / (run_den[rv] + alpha)

    P = [0.0 for _ in range(2 * sdim)]
    total = 2 * sdim

    for mv in range(2):
        for rv in range(sdim):
            prior = 0.45 * my_p[mv] + 0.25 * run_p[rv] + 0.30 * base_p
            if den[mv][rv] > 0.0:
                pv = (num[mv][rv] + 2.0 * prior) / (den[mv][rv] + 2.0)
            else:
                pv = prior

            if rv == 0:
                if friendly:
                    boost = 0.58 if mv == 0 else 0.32
                    if mv == 0 and opp_C_streak >= 8:
                        boost = 0.65
                else:
                    boost = 0.22
                if pv < boost:
                    pv = boost
            else:
                if mv == 0:
                    if friendly and rv <= 4:
                        boost = 0.60 - 0.03 * rv
                    elif friendly and rv == 5:
                        boost = 0.30
                    else:
                        boost = -1.0
                    if boost >= 0.0 and pv < boost:
                        pv = boost
                    if (not friendly or rv > 5):
                        if overall_opp < 0.25 and pv > 0.25:
                            pv = 0.25
                        if recent_opp < 0.20 and pv > 0.30:
                            pv = 0.30
                else:
                    if friendly and rv <= 5:
                        boost = 0.32 - 0.02 * rv
                        if pv < boost:
                            pv = boost
                    else:
                        if overall_opp < 0.30 and pv > 0.30:
                            pv = 0.30

            if pv < 0.0:
                pv = 0.0
            elif pv > 1.0:
                pv = 1.0
            P[mv * sdim + rv] = pv

    next_C_C = [0 for _ in range(total)]
    next_C_D = [0 for _ in range(total)]
    next_D_C = [0 for _ in range(total)]
    next_D_D = [0 for _ in range(total)]

    for mv in range(2):
        for rv in range(sdim):
            idx = mv * sdim + rv
            nrv = rv + 1 if rv < cap else cap
            next_C_C[idx] = 0
            next_C_D[idx] = nrv
            next_D_C[idx] = sdim
            next_D_D[idx] = sdim + nrv

    future = min(20, 99 - n)
    V = [0.0 for _ in range(total)]
    PP = P
    NCC = next_C_C
    NCD = next_C_D
    NDC = next_D_C
    NDD = next_D_D

    for _ in range(future):
        old = V
        new = [0.0 for _ in range(total)]
        for idx in range(total):
            pc = PP[idx]
            q = 1.0 - pc
            ec = pc * (3.0 + old[NCC[idx]]) + q * old[NCD[idx]]
            ed = pc * (5.0 + old[NDC[idx]]) + q * (1.0 + old[NDD[idx]])
            new[idx] = ec if ec >= ed else ed
        V = new

    cur_rv = opp_D_streak if opp_D_streak < cap else cap
    cur_idx = my[-1] * sdim + cur_rv
    nrv = cur_rv + 1 if cur_rv < cap else cap
    pc = P[cur_idx]
    q = 1.0 - pc

    valC = pc * (3.0 + V[0]) + q * V[nrv]
    valD = pc * (5.0 + V[sdim]) + q * (1.0 + V[sdim + nrv])

    if valC >= valD:
        action = 'C'
    else:
        action = 'D'

    if abs(valC - valD) < 0.8:
        if friendly:
            action = 'C' if rng.random() < 0.62 else 'D'
        else:
            action = 'D' if rng.random() < 0.58 else 'C'

    if action == 'D':
        if my[-1] == 0 and opp_D_streak <= 4 and friendly and (100 - n) > 5:
            if my_C_streak >= opp_D_streak:
                action = 'C'
        if mutual_D_streak >= 1 and opp_D_streak <= 4 and friendly and (100 - n) > 10:
            if rng.random() < 0.25:
                action = 'C'

    if action == 'C' and op[-1] == 0 and (100 - n) > 3:
        if n >= 2 and my[-1] == 1 and my[-2] == 1 and op[-1] == 0 and op[-2] == 0:
            action = 'D'
        elif overall_opp >= 0.90 and recent_opp >= 0.90 and opp_C_streak >= 12:
            if rng.random() < 0.02:
                action = 'D'

    return action

