    last_opp = opp[-1]

    streak_oppD = 0
    for a in reversed(opp):
        if a == 'D':
            streak_oppD += 1
        else:
            break

    streak_dd = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and opp[i] == 'D':
            streak_dd += 1
        else:
            break

    if opp_def == n:
        return 'D'

    if n >= 5 and my_def == 0:
        o5 = tuple(opp[-5:])
        if (o5 == ('D', 'D', 'C', 'C', 'C') or
            o5 == ('D', 'C', 'C', 'C', 'D') or
            o5 == ('C', 'C', 'C', 'D', 'D') or
            o5 == ('C', 'C', 'D', 'D', 'C') or
            o5 == ('C', 'D', 'D', 'C', 'C')):
            return 'D'

    if last_opp == 'D' and streak_oppD >= 3 and my_def == 0:
        return 'D'

    if my_def == 0 and 30 <= n <= 45 and 1 <= opp_def <= 10 and last_opp == 'C':
        return 'D'

    if n >= 15 and streak_oppD >= 5 and opp_def * 2 >= n:
        return 'D'

    if streak_dd >= 2 and opp_def <= 6 and opp_def * 2 < n:
        return 'C'

    decay = 0.93

    global_c = 0.0
    global_w = 0.0
    w = 1.0
    for i in range(n - 1, -1, -1):
        global_w += w
        if opp[i] == 'C':
            global_c += w
        w *= decay

    if global_w > 0.0:
        gc = global_c / global_w
    else:
        gc = 0.75

    wC = [0.0, 0.0, 0.0, 0.0]
    wD = [0.0, 0.0, 0.0, 0.0]
    mC = [0.0, 0.0]
    mD = [0.0, 0.0]

    w = 1.0
    for j in range(n - 2, -1, -1):
        si = (0 if me[j] == 'C' else 2) + (0 if opp[j] == 'C' else 1)
        ro = opp[j + 1]

        if ro == 'C':
            wC[si] += w
        else:
            wD[si] += w

        mi = 0 if me[j] == 'C' else 1
