def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'
    if n < 2:
        return 'C'

    last_m, last_o = history[-1]

    recent10 = history[-10:] if n >= 10 else history
    recent_opp_c = 0
    for _, o in recent10:
        if o == 'C':
            recent_opp_c += 1

    recent20 = history[-20:] if n >= 20 else history
    dc_count = 0
    for m, o in recent20:
        if m == 'D' and o == 'C':
            dc_count += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    if last_o == 'D' and opp_d_streak >= 6 and recent_opp_c <= 3:
        return 'D'

    if last_m == 'C' and last_o == 'C' and n < 95 and recent_opp_c >= 8:
        if dc_count >= 4:
            pass
        else:
            if rng.random() < 0.02:
                return 'D'
            return 'C'

    if last_m == 'C' and last_o == 'D' and n < 95 and opp_d_streak <= 1 and recent_opp_c >= 8:
        return 'C'

    if last_m == 'D' and last_o == 'D' and n > 20 and recent_opp_c <= 1:
        return 'D'

    ec = [0.0] * 4
    et = [0.0] * 4
    mc = [0.0, 0.0]
    mt = [0.0, 0.0]
    gc = 0.0
    gt = 0.0

    for i in range(n):
        w = 4.0 if i >= n - 3 else (2.0 if i >= n - 10 else 1.0)
        if history[i][1] == 'C':
            gc += w
        gt += w

    for i in range(1, n):
        pm, po = history[i - 1]
        co = history[i][1]
        w = 4.0 if i >= n - 3 else (2.0 if i >= n - 10 else 1.0)
        s = (1 if pm == 'D' else 0) * 2 + (1 if po == 'D' else 0)
        is_c = 1.0 if co == 'C' else 0.0
        my_bit = 1 if pm == 'D' else 0
        ec[s] += w * is_c
        et[s] += w
        mc[my_bit] += w * is_c
        mt[my_bit] += w

    opp_all = 0
    for _, o in history:
        if o == 'C':
            opp_all += 1

    p_recent = gc / gt if gt > 0.0 else 0.75
    p_all = opp_all / float(n) if n > 0 else 0.75
    p_global = 0.75 * p_recent + 0.25 * p_all
    if p_global < 0.02:
        p_global = 0.02
    elif p_global > 0.98:
        p_global = 0.98

    base = [0.82, 0.65, 0.30, 0.22]
    alpha = 5.5
    plist = [0.0] * 4

    for s in range(4):
        my_bit = s // 2
        if mt[my_bit] > 0.0:
            mp = mc[my_bit] / mt[my_bit]
        else:
            mp = 0.80 if my_bit == 0 else 0.30

        prior = 0.50 * base[s] + 0.30 * mp + 0.20 * p_global

        if s == 0:
            if recent_opp_c >= 8:
                prior += 0.12
            elif recent_opp_c <= 3:
                prior -= 0.12
        elif s == 1:
            if opp_d_streak <= 1 and recent_opp_c >= 8:
                prior += 0.15
            elif opp_d_streak >= 3:
                prior -= 0.12 * (opp_d_streak - 2)
            if recent_opp_c <= 2:
                prior -= 0.12
        elif s == 2:
            if recent_opp_c >= 8:
                prior += 0.05
            if dc_count >= 4:
                prior += 0.10
            if recent_opp_c <= 2:
                prior -= 0.10
        else:
            if recent_opp_c >= 6:
                prior += 0.15
            elif recent_opp_c <= 2:
                prior -= 0.08

        if prior < 0.05:
            prior = 0.05
        elif prior > 0.95:
            prior = 0.95

        if et[s] > 0.0:
            p = (ec[s] + alpha * prior) / (et[s] + alpha)
        else:
            p = prior

        if p < 0.03:
            p = 0.03
        elif p > 0.97:
            p = 0.97

        plist[s] = p

    s0 = (1 if last_m == 'D' else 0) * 2 + (1 if last_o == 'D' else 0)
    r = 100 - n
    v = [0.0, 0.0, 0.0, 0.0]

    for _ in range(r - 1):
        nv = [0.0, 0.0, 0.0, 0.0]
        for s in range(4):
            p = plist[s]
            q = 1.0 - p
            vc = p * (3.0 + v[0]) + q * v[1]
            vd = p * (5.0 + v[2]) + q * (1.0 + v[3])
            nv[s] = vd if vd > vc + 1e-12 else vc
        v = nv

    p = plist[s0]
    q = 1.0 - p
    vc = p * (3.0 + v[0]) + q * v[1]
    vd = p * (5.0 + v[2]) + q * (1.0 + v[3])

    if vd > vc + 1e-12:
        return 'D'
    return 'C'

