        m, o = history[i]

        if o == 'C':
            opp_c += 1
        else:
            cur_d += 1
            if not in_d:
                episodes += 1
                in_d = True
            if cur_d > max_d_streak:
                max_d_streak = cur_d

        if i > 0:
            prev_my = history[i - 1][0]

            # Opponent defected after we cooperated.
            if o == 'D' and prev_my == 'C':
                unprovoked += 1

            # Opponent's response to our previous defection.
            if prev_my == 'D':
                total_after_d += 1
                if o == 'C':
                    coop_after_d += 1

        if o == 'C':
            in_d = False
            cur_d = 0

    opp_d = n - opp_c
    opp_rate = (opp_c + 2.0) / (n + 4.0)

    if opp_c == 0:
        return 'D'

    streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_d += 1
