def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last = history[n - 1][0]
    opp_last = history[n - 1][1]

    streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        streak += 1
        i -= 1

    start = n - 8
    if start < 0:
        start = 0
    recentD = 0
    for j in range(start, n):
        if history[j][1] == 'D':
            recentD += 1

    reset_active = False
    for off in range(0, 2):
        k = n - 1 - off
        if k < 0:
            break
        if history[k][0] == 'D' and history[k][1] == 'D':
            has_cc = False
            for m in range(k + 1, n):
                if history[m][0] == 'C' and history[m][1] == 'C':
                    has_cc = True
                    break
            if not has_cc:
                reset_active = True
            break

    if opp_last == 'D':
        if streak >= 5 or recentD >= 7:
            return 'D'
        if reset_active:
            return 'C'
        if streak == 1 and my_last == 'C' and recentD <= 1:
            return 'C'
        return 'D'

    if my_last == 'D':
        return 'D'

    return 'C'

