def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_D = 0
    my_D = 0
    for m, o in history:
        if o == 'D':
            opp_D += 1
        if m == 'D':
            my_D += 1

    opp_C = n - opp_D

    if opp_D == n:
        return 'D'

    last6 = history[-6:]
    rec6_D = 0
    for m, o in last6:
        if o == 'D':
            rec6_D += 1

    mutual_D_streak = 0
    for m, o in reversed(history):
        if m == 'D' and o == 'D':
            mutual_D_streak += 1
        else:
            break

