    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    remaining = 100 - n
    denom = max(1, n - 1)

    opp_c = 0
    my_c = 0
    w_c = 0.0
    w_sum = 0.0
    for i in range(n):
        m, o = history[i]
        w = 1.0 + (i / denom) * 2.0
        w_sum += w
        if o == 'C':
            opp_c += 1
            w_c += w
        if m == 'C':
            my_c += 1

    opp_rate = opp_c / n
    w_rate = w_c / w_sum if w_sum > 0 else 0.5
    my_rate = my_c / n

    rw = n if n < 16 else 16
    rs = n - rw
    rec_c = 0
    rec_m_c = 0
    for i in range(rs, n):
        m, o = history[i]
        if o == 'C':
            rec_c += 1
        if m == 'C':
            rec_m_c += 1
    rec_rate = rec_c / rw if rw > 0 else 0.5
    rec_m_rate = rec_m_c / rw if rw > 0 else 0.5

    ts = max(1, n - 16)
    c_cc = c_count = d_dc = d_count = mimic_m = mimic_t = 0
    for i in range(ts, n):
        pm = history[i - 1][0]
        co = history[i][1]
        mimic_t += 1
        if co == pm:
            mimic_m += 1
        if pm == 'C':
            c_count += 1
            if co == 'C':
                c_cc += 1
        else:
            d_count += 1
            if co == 'C':
                d_dc += 1

    p_cifc = c_cc / c_count if c_count > 0 else rec_rate
    p_cifd = d_dc / d_count if d_count > 0 else rec_rate
    mimic = mimic_m / mimic_t if mimic_t > 0 else 0.5

    streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak_d += 1
        else:
            break

    pre_cc = 0
    start = n - streak_d - 1
    while start >= 0:
        m, o = history[start]
        if m == 'C' and o == 'C':
            pre_cc += 1
            start -= 1
        else:
            break

    hostile = False
