def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'
    if n == 99:
        return 'D'

    opp_c = 0
    my_d = 0
    dd = 0
    d_to_c = 0
    d_to_d = 0

    for i in range(n):
        m = history[i][0]
        o = history[i][1]
        if m == 'D':
            my_d += 1
            if o == 'D':
                dd += 1
        if o == 'C':
            opp_c += 1

    for i in range(1, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                d_to_c += 1
            else:
                d_to_d += 1

    w = n if n < 20 else 20
    start = n - w

    recent_opp_c = 0
    recent_c_to_d = 0

    for i in range(start, n):
        if history[i][1] == 'C':
            recent_opp_c += 1

    for i in range(max(1, start), n):
        if history[i - 1][0] == 'C' and history[i][1] == 'D':
            recent_c_to_d += 1

    c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            c_streak += 1
        else:
            break

    last_me = history[-1][0]
    last_op = history[-1][1]

    if opp_c >= 10:
        max_forgive = 4
    elif opp_c >= 5:
        max_forgive = 2
    else:
        max_forgive = 1

    exploit_limit = max_forgive + 1
    if exploit_limit > 5:
        exploit_limit = 5

    if (my_d == 0 and n >= 20 and last_op == 'C' and c_streak >= 10 and
        recent_opp_c * 4 >= w * 3):
        return 'D'

    if (my_d > 0 and d_to_c >= 1 and d_to_d == 0 and dd == 0 and
        recent_c_to_d <= exploit_limit and recent_opp_c * 4 >= w * 3):
        if (last_me == 'C' and last_op == 'C') or (last_me == 'D' and last_op == 'C'):
            return 'D'

    if last_op == 'D':
        if recent_c_to_d <= max_forgive and recent_opp_c * 2 >= w and opp_c * 2 > n:
            return 'C'
        if d_to_c >= 1 and recent_c_to_d <= 2 and opp_c * 3 > n * 2:
            return 'C'
        if opp_c * 4 > n * 3 and recent_c_to_d <= 1:
            return 'C'
        if recent_c_to_d <= 1 and recent_opp_c * 3 >= w * 2:
            return 'C'
        return 'D'

    if opp_c * 3 > n * 2:
        return 'C'

    if recent_opp_c * 2 < w and recent_c_to_d > 2:
        return 'D'

    return 'C'

