def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    my_c = 0
    for own, opp in history:
        if opp == 'C':
            opp_c += 1
        if own == 'C':
            my_c += 1

    opp_d = n - opp_c
    my_d = n - my_c

    if n >= 99:
        if opp_d > 0 or my_d > 0:
            return 'D'
        return 'C'

    own_last, opp_last = history[-1]

    if opp_last == 'C':
        return 'C'

    streak = 0
    for own, opp in reversed(history):
        if opp == 'D':
            streak += 1
        else:
            break

    rate = opp_c / n

    if streak == 1:
        if own_last == 'C':
            return 'C'
        w = n if n < 10 else 10
        recent_c = 0
        for i in range(n - w, n):
            if history[i][1] == 'C':
                recent_c += 1
        recent_c = recent_c / w
        if rate > 0.6 or recent_c > 0.6:
            return 'C'
        return 'D'

    if streak == 4 and own_last == 'D':
        return 'C'

    if streak == 5 and own_last == 'C':
        if n >= 2 and history[-2][0] == 'D':
            return 'C'

    return 'D'

