def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [a for a, b in history]
    op = [b for a, b in history]

    opD = op.count('D')
    opC = n - opD
    if opC == 0:
        return 'D'

    myD = my.count('D')
    last_m = my[-1]
    last_o = op[-1]

    run_d = 0
    for x in reversed(op):
        if x == 'D':
            run_d += 1
        else:
            break

    druns = 0
    prev = 'C'
    for x in op:
        if x == 'D' and prev == 'C':
            druns += 1
        prev = x

    if n >= 20 and druns >= 2 and opD * 4 > n:
        return 'D'

    if last_o == 'D':
        if last_m == 'C' and run_d <= 4 and druns <= 1:
            return 'C'
        if last_m == 'D' and druns > 1 and myD > opD and opD * 4 <= n:
            return 'C'
        return 'D'

    return 'C'

