    if not history:
        return 'C'
    n = len(history)
    if n >= 99:
        return 'D'
    last_me, last_opp = history[-1]
    if n < 8:
        return 'C' if last_opp == 'C' else 'D'
    opp_c = 0
    my_c = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        if b == 'C':
            opp_c += 1
    recent = history[-12:] if n >= 12 else history
    recent_c = sum(1 for a, b in recent if b == 'C')
    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break
    perceived = opp_c / n
    if last_opp == 'C' and last_me == 'D' and opp_c == n:
        return 'D'
    if recent_c == 0:
        if rng.random() < 0.04:
            return 'C'
        return 'D'
    if opp_c <= 3 and n >= 20:
        return 'D'
    if recent_c >= 11:
        if opp_c == n and last_opp == 'C' and last_me == 'C' and n >= 20:
            if rng.random() < 0.02:
                return 'D'
        return 'C'
    if perceived > 0.65:
