def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_op = history[-1]
    op_c = 0
    ctx_total = {'CC': 0, 'CD': 0, 'DC': 0, 'DD': 0}
    ctx_c = {'CC': 0, 'CD': 0, 'DC': 0, 'DD': 0}
    after_myD_C = 0
    after_myD_D = 0
    unprov = 0

    for i in range(n):
        m, o = history[i]
        if o == 'C':
            op_c += 1
        if o == 'D' and (i == 0 or history[i - 1][0] == 'C'):
            unprov += 1
        if i + 1 < n:
            oo = history[i + 1][1]
            key = m + o
            ctx_total[key] += 1
            if oo == 'C':
                ctx_c[key] += 1
            if m == 'D':
                if oo == 'C':
                    after_myD_C += 1
                else:
                    after_myD_D += 1

    rate = op_c / n
    rlen = 12 if n >= 12 else n
    recent_d = 0
    recent_unprov = 0
    start = n - rlen
    for i in range(start, n):
        o = history[i][1]
        if o == 'D':
            recent_d += 1
            if i == 0 or history[i - 1][0] == 'C':
                recent_unprov += 1

    opp_d_run = 0
    if last_op == 'D':
        i = n - 1
        while i >= 0 and history[i][1] == 'D':
            opp_d_run += 1
            i -= 1

    hostile = (recent_unprov >= 4) or (recent_d >= 9 and recent_unprov >= 2) or (rate < 0.3 and recent_d >= 7)
    tolerant = ((after_myD_C >= 2 and after_myD_C > after_myD_D) or
                (rate >= 0.9 and after_myD_C >= 1 and after_myD_D == 0 and n >= 8))

    def prob_for(key):
        total = ctx_total[key]
        c = ctx_c[key]
        if key == 'CC':
            if hostile:
                prior = 0.25
            elif rate >= 0.8:
                prior = 0.9
            elif rate >= 0.5:
                prior = 0.6
            elif rate >= 0.25:
                prior = 0.35
            else:
                prior = 0.15
        elif key == 'CD':
            if hostile or recent_unprov >= 2:
                prior = 0.12
            elif tolerant:
                prior = 0.75
            elif rate >= 0.9:
                prior = 0.7
            elif rate >= 0.6:
                prior = 0.5
            else:
                prior = 0.35
        elif key == 'DC':
            if tolerant:
                prior = 0.85
            elif hostile:
                prior = 0.15
            elif rate >= 0.9:
                prior = 0.3
            elif rate >= 0.6:
                prior = 0.35
            else:
                prior = 0.3
        else:
            if hostile:
                prior = 0.08
            elif tolerant:
                prior = 0.8
            elif rate >= 0.75:
                prior = 0.22
            elif rate >= 0.5:
                prior = 0.35
            else:
                prior = 0.18
        return (c + prior * 2.0) / (total + 2.0)

    if last_me == 'D' and last_op == 'D' and opp_d_run == 4 and rate >= 0.65 and recent_d <= 5 and not hostile:
        return 'C'

    if tolerant and last_op == 'C' and rate >= 0.6:
        if rng.random() < 0.75:
            return 'D'

    pC = prob_for(last_me + last_op)
    pD = 1.0 - pC
    p_next_C = pC * prob_for('CC') + pD * prob_for('CD')
    p_next_D = pC * prob_for('DC') + pD * prob_for('DD')

    if n == 98:
        valC = 3.0 * pC + 1.0 + 4.0 * p_next_C
        valD = 5.0 * pC + 1.0 * (1.0 - pC) + 1.0 + 4.0 * p_next_D
    else:
        valC = 3.0 * pC + 1.0 + 2.0 * p_next_C
        valD = 5.0 * pC + 1.0 * (1.0 - pC) + 1.0 + 2.0 * p_next_D

    if hostile:
        bias = -1.5
    elif tolerant:
        bias = -0.1
    else:
        if rate >= 0.9:
            bias = 1.2
        elif rate >= 0.75:
            bias = 0.8
        elif rate >= 0.5:
            bias = 0.4
        elif rate >= 0.3:
            bias = -0.2
        else:
            bias = -0.7
        if n >= 90 and recent_unprov == 0 and rate >= 0.9:
            bias -= 0.4
        if n >= 96 and recent_unprov == 0 and rate >= 0.9:
            bias -= 0.3

    if valD > valC + bias:
        return 'D'

    if last_op == 'C' and rate >= 0.9 and recent_unprov <= 1 and n >= 84 and not hostile and not tolerant:
        if rng.random() < 0.12:
            return 'D'

