    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = 0
    for o in op:
        if o == 'C':
            op_c += 1
    op_d = n - op_c

    last = op[-1]
    run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == last:
            run += 1
        else:
            break

    punished = 0
    forgiven = 0
    betrayed = 0
    rewarded = 0

    for i in range(1, n):
        if me[i - 1] == 'D':
            if op[i] == 'D':
                punished += 1
            else:
                forgiven += 1
        else:
            if op[i] == 'C':
                rewarded += 1
            else:
                betrayed += 1

    if forgiven >= 2 and forgiven > punished:
        return 'D'

    if op_c == 0:
        return 'D'

    if last == 'D':
        if run >= 4:
            if me[-1] == 'D' and run <= 6 and op_c * 5 >= n * 3:
                return 'C'
            return 'D'

        if run == 1:
            if op_c * 5 >= n * 3:
                return 'C'
            return 'D'

        if op_c * 5 >= n * 3 and betrayed * 5 <= n * 2:
            return 'C'
        return 'D'

    if me[-1] == 'D':
        if op_c * 5 < n * 3:
            return 'D'
        return 'C'

    if (
