    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    if n <= 2 and opp_last == 'D':
        return 'D'
    if n <= 1:
        return 'C'
    if n >= 99:
        return 'D'

    rounds_left = 100 - n

    opp_d = 0
    for _, o in history:
        if o == 'D':
            opp_d += 1
    overall_coop = (n - opp_d) / n

    d_streak = 0
    for _, o in reversed(history):
        if o == 'D':
            d_streak += 1
        else:
            break

    c_streak = 0
    for _, o in reversed(history):
        if o == 'C':
            c_streak += 1
        else:
            break

    dd_streak = 0
    for m, o in reversed(history):
        if m == 'D' and o == 'D':
            dd_streak += 1
        else:
            break

    start = 0 if n < 5 else n - 5
    recent5_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent5_d += 1

    start = 0 if n < 10 else n - 10
    recent10_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent10_d += 1

    start = 0 if n < 20 else n - 20
    recent20_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent20_d += 1

    cd_count = 0
    for m, o in history:
        if m == 'C' and o == 'D':
            cd_count += 1

    matches = 0
    trans = 0
    punish = 0
    nonpunish = 0
    for i in range(1, n):
        if history[i][1] == history[i - 1][0]:
            matches += 1
        if history[i - 1][0] == 'D':
            trans += 1
            if history[i][1] == 'D':
                punish += 1
            else:
                nonpunish += 1
    mirror = matches / (n - 1) if n > 1 else 0.5

    if overall_coop < 0.3 and d_streak >= 3:
        return 'D'
    if recent10_d >= 8 and overall_coop < 0.6:
        return 'D'
    if recent20_d >= 17 and overall_coop < 0.45:
        return 'D'
    if d_streak >= 6 and c_streak == 0:
        return 'D'

    if opp_last == 'D':
        if d_streak <= 4 and overall_coop >= 0.6 and recent10_d <= 5:
            return 'C'
        if d_streak >= 5 and c_streak == 0 and overall_coop < 0.85:
            return 'D'
        if cd_count <= 1 and overall_coop >= 0.75 and recent10_d <= 2:
            return 'C'

        if dd_streak >= 2 and (mirror >= 0.45 or overall_coop >= 0.3 or recent10_d <= 5):
            return 'C'

        if my_last == 'D':
            if recent5_d <= 4 and overall_coop >= 0.5:
